import { Component } from '@angular/core';
import { bootstrapApplication } from '@angular/platform-browser';

@Component({
  selector: 'app-root',
  template: `
    <main>
      <h1>{{ title }}</h1>
      <button (click)="rename()">Rename shop</button>
    </main>
  `,
})
class AppComponent {
  title = 'Corner Shop';
  rename() { this.title = 'Neighbourhood Shop'; }
}

bootstrapApplication(AppComponent).catch(console.error);
