import { Component } from '@angular/core';
import { bootstrapApplication } from '@angular/platform-browser';

@Component({ selector: 'welcome-card', template: '<p>Welcome, {{ name }}.</p>' })
class WelcomeCard { name = 'Mina'; }

@Component({
  selector: 'app-root',
  imports: [WelcomeCard],
  template: '<h1>Dashboard</h1><welcome-card />',
})
class AppComponent {}

bootstrapApplication(AppComponent, { providers: [] }).catch(console.error);
